import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.BL79I5mR.js";const m=JSON.parse('{"title":"LocalSWMM Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function i(s,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="localswmm-documentation" tabindex="-1">LocalSWMM Documentation <a class="header-anchor" href="#localswmm-documentation" aria-label="Permalink to &quot;LocalSWMM Documentation&quot;">​</a></h1><p>LocalSWMM is a web application for 1D hydraulic modeling and simulation of stormwater and wastewater networks. The core of this project is based on the <a href="https://www.hydrocouple.org/openswmm.engine/" target="_blank" rel="noreferrer">HydroCouple OpenSWMM engine</a>, which was compiled to WebAssembly and runs entirely in the browser.</p><p>The following documentation has been redacted by the author based on <a href="https://diataxis.fr/" target="_blank" rel="noreferrer">Diátaxis</a>, which divides documentation by the user needs into four quadrants:</p><table tabindex="0"><thead><tr><th>Quadrant</th><th>Answers</th><th>Read it when</th></tr></thead><tbody><tr><td><a href="./tutorials/">Tutorials</a></td><td>learning</td><td>You want to learn how to build and simulate networks, step by step, from scratch.</td></tr><tr><td><a href="./how-to/">How-to guides</a></td><td>doing</td><td>You want to accomplish a concrete task: run the app, configure it, build from source, deploy, fix a problem.</td></tr><tr><td><a href="./reference/">Reference</a></td><td>knowing</td><td>You need an exact fact, such as data formats, engine options, glossary terms.</td></tr><tr><td><a href="./explanation/">Explanation</a></td><td>understanding</td><td>You want to understand <em>how and why</em> the engine computes what it computes: architecture, 1D hydraulics, engine modifications.</td></tr></tbody></table><h2 id="orientation" tabindex="-1">Orientation <a class="header-anchor" href="#orientation" aria-label="Permalink to &quot;Orientation&quot;">​</a></h2><p>If this is your first time using SWMM based products, the author heavily suggests diving into the <a href="https://www.epa.gov/water-research/storm-water-management-model-swmm" target="_blank" rel="noreferrer">official SWMM documentation</a> before even considering using this app, mainly because some of the legacy methods that the OpenSWMM engine uses have already been documented by the <a href="https://www.openswmm.org/Code/Home" target="_blank" rel="noreferrer">OpenSWMM community</a>, this project is focused on the newer methods that have been discussed and implemented by the OpenSWMM community since 2023.</p><ul><li><strong>New to LocalSWMM?</strong> Start with the <a href="./tutorials/">tutorials</a> — they teach by doing.</li><li><strong>Have a specific task?</strong> Go straight to the <a href="./how-to/">how-to guides</a>.</li><li><strong>Need a fact?</strong> Look it up in the <a href="./reference/">reference</a>.</li><li><strong>Want to understand the math or the architecture?</strong> Read the <a href="./explanation/">explanation</a>.</li></ul><h2 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;Languages&quot;">​</a></h2><ul><li><a href="/docs/">English</a> (primary)</li><li><a href="/docs/es/">Español</a></li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="https://github.com/JoaquinAlvarado-py/LocalSWMM" target="_blank" rel="noreferrer">Repository README</a> . Where you can find the project overview and quick start</li><li><a href="https://github.com/JoaquinAlvarado-py/LocalSWMM/blob/experimental/CONTEXT.md" target="_blank" rel="noreferrer">CONTEXT.md</a> . Domain glossary and terminology (Español)</li></ul>',11)])])}const p=t(n,[["render",i]]);export{m as __pageData,p as default};
